class Konto:
    def __init__(self, inhaber, kontostand=0):
        self.inhaber = inhaber
        self.kontostand = kontostand

    def einzahlen(self, betrag):
        if betrag <= 0:
            raise ValueError("Betrag muss positiv sein")
        self.kontostand += betrag

    def abheben(self, betrag):
        if betrag > self.kontostand:
            raise ValueError("Nicht genug Guthaben")
        self.kontostand -= betrag

    def __str__(self):
        return f"Konto von {self.inhaber}: {self.kontostand} €"


konto = Konto("Anna")
konto.einzahlen(100)
konto.abheben(30)
print(konto)

import random


def bewerte(geheim, tipp):
    if tipp < geheim:
        return "zu klein"
    elif tipp > geheim:
        return "zu groß"
    else:
        return "richtig"


def spiele(geheim):
    versuche = 0
    while True:
        tipp = int(input("Dein Tipp: "))
        versuche += 1
        ergebnis = bewerte(geheim, tipp)
        print(ergebnis)
        if ergebnis == "richtig":
            print(f"Geschafft in {versuche} Versuchen!")
            return versuche


if __name__ == "__main__":
    print("Ich denke mir eine Zahl zwischen 1 und 100.")
    spiele(random.randint(1, 100))
